package com.bank.spark.service;

import com.bank.spark.model.TaskLoad;
import java.util.List;
import java.util.logging.Logger;

// Computes per-task spill and classifies the likely cause.
public class SpillAnalyzer {

    private static final Logger log = Logger.getLogger(SpillAnalyzer.class.getName());

    private final long perTaskMemoryMb;

    public SpillAnalyzer(long perTaskMemoryMb) {
        this.perTaskMemoryMb = perTaskMemoryMb;
    }

    // Spill for a task = data beyond what fits in memory (0 if it fits).
    public long spillFor(TaskLoad t) {
        return Math.max(0, t.getDataMb() - perTaskMemoryMb);
    }

    // Classify: concentrated spill = skew; uniform spill = volume/partitions.
    public String classify(List<TaskLoad> tasks) {
        long maxSpill = tasks.stream().mapToLong(this::spillFor).max().orElse(0);
        if (maxSpill == 0) {
            log.info("No spill — stage fits in execution memory");
            return "NO SPILL — healthy";
        }
        long spillingTasks = tasks.stream().filter(t -> spillFor(t) > 0).count();
        double fraction = (double) spillingTasks / tasks.size();
        if (fraction <= 0.25) {
            log.warning(() -> spillingTasks + "/" + tasks.size()
                    + " tasks spill heavily → concentrated → SKEW");
            return "CONCENTRATED SPILL — data skew; use AQE skew join / salt / isolate";
        }
        log.warning(() -> spillingTasks + "/" + tasks.size()
                + " tasks spill → uniform → volume/partitions");
        return "UNIFORM SPILL — raise shuffle.partitions / executor memory, unpersist caches";
    }
}
