package com.bank.spark;

import com.bank.spark.model.TaskLoad;
import com.bank.spark.service.SpillAnalyzer;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: compute spill and classify its cause for two stages.
public class SpillAnalysisDemo {

    private static final Logger log = Logger.getLogger(SpillAnalysisDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Each task has 256 MB of execution memory available.
        SpillAnalyzer analyzer = new SpillAnalyzer(256);

        // Uniform-spill stage: every task is 400 MB (too few partitions).
        List<TaskLoad> uniform = List.of(
            new TaskLoad(0, 400), new TaskLoad(1, 410),
            new TaskLoad(2, 395), new TaskLoad(3, 405));

        // Concentrated-spill stage: one task is 2000 MB (skew), rest fit.
        List<TaskLoad> skewed = List.of(
            new TaskLoad(0, 200), new TaskLoad(1, 2000),
            new TaskLoad(2, 210), new TaskLoad(3, 190));

        log.info("Stage A (uniform): " + analyzer.classify(uniform));
        log.info("Stage B (skewed):  " + analyzer.classify(skewed));
        log.info(() -> "Task 1 of Stage B spilled " + analyzer.spillFor(skewed.get(1)) + "MB");
        log.info("Spill analysis demo complete.");
    }
}
